/* Claymorphism Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="claymorphism-light"] {
  --background: hsl(0 0% 89.56%);
  --foreground: hsl(217.27 35.09% 17.61%);
  --card: hsl(300 0% 96.06%);
  --card-foreground: hsl(217.27 35.09% 17.61%);
  --popover: hsl(300 0% 96.06%);
  --popover-foreground: hsl(217.27 35.09% 17.61%);
  --primary: hsl(238.34 82.68% 66.83%);
  --primary-foreground: hsl(300 50% 100%);
  --secondary: hsl(340 0% 83.14%);
  --secondary-foreground: hsl(214.99 15.5% 34.68%);
  --muted: hsl(0 0% 89.56%);
  --muted-foreground: hsl(219.97 7.71% 45.75%);
  --accent: hsl(292.48 54.97% 93.41%);
  --accent-foreground: hsl(216.92 18.93% 26.34%);
  --destructive: hsl(359.91 86.11% 60.55%);
  --destructive-foreground: hsl(300 50% 100%);
  --border: hsl(340 0% 83.14%);
  --input: hsl(340 0% 83.14%);
  --ring: hsl(238.34 82.68% 66.83%);
  --chart-1: hsl(238.34 82.68% 66.83%);
  --chart-2: hsl(243.42 75.19% 58.54%);
  --chart-3: hsl(243.79 56.66% 50.88%);
  --chart-4: hsl(243.92 55.13% 41.68%);
  --chart-5: hsl(242.69 48.79% 34.69%);
  --radius: 1.25rem;
  --sidebar: hsl(340 0% 83.14%);
  --sidebar-foreground: hsl(217.27 35.09% 17.61%);
  --sidebar-primary: hsl(238.34 82.68% 66.83%);
  --sidebar-primary-foreground: hsl(300 50% 100%);
  --sidebar-accent: hsl(292.48 54.97% 93.41%);
  --sidebar-accent-foreground: hsl(216.92 18.93% 26.34%);
  --sidebar-border: hsl(340 0% 83.14%);
  --sidebar-ring: hsl(238.34 82.68% 66.83%);
  --font-sans: Plus Jakarta Sans, sans-serif;
  --font-serif: Lora, serif;
  --font-mono: Roboto Mono, monospace;
  --shadow-color: hsl(240 4% 60%);
  --shadow-opacity: 0.18;
  --shadow-blur: 10px;
  --shadow-spread: 4px;
  --shadow-offset-x: 2px;
  --shadow-offset-y: 2px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 2px 2px 10px 4px hsl(240 4% 60% / 0.09);
  --shadow-xs: 2px 2px 10px 4px hsl(240 4% 60% / 0.09);
  --shadow-sm:
    2px 2px 10px 4px hsl(240 4% 60% / 0.18),
    2px 1px 2px 3px hsl(240 4% 60% / 0.18);
  --shadow:
    2px 2px 10px 4px hsl(240 4% 60% / 0.18),
    2px 1px 2px 3px hsl(240 4% 60% / 0.18);
  --shadow-md:
    2px 2px 10px 4px hsl(240 4% 60% / 0.18),
    2px 2px 4px 3px hsl(240 4% 60% / 0.18);
  --shadow-lg:
    2px 2px 10px 4px hsl(240 4% 60% / 0.18),
    2px 4px 6px 3px hsl(240 4% 60% / 0.18);
  --shadow-xl:
    2px 2px 10px 4px hsl(240 4% 60% / 0.18),
    2px 8px 10px 3px hsl(240 4% 60% / 0.18);
  --shadow-2xl: 2px 2px 10px 4px hsl(240 4% 60% / 0.45);
  --tracking-normal: 0em;
}

